ALTER TABLE player_rankings ADD COLUMN reborn INTEGER NOT NULL DEFAULT 0;
UPDATE player_rankings SET reborn=COALESCE((SELECT MIN(10,MAX(0,CAST(COALESCE(json_extract(CASE WHEN slot.type='object' THEN slot.value ELSE '{}' END,'$.rw.stat.reborn'),0) AS INTEGER))) FROM cloud_saves AS save,json_each(CASE WHEN json_valid(save.snapshot) THEN save.snapshot ELSE '{"slots":[]}' END,'$.slots') AS slot WHERE save.account_id=substr(player_rankings.actor_key,9) AND json_valid(save.snapshot) AND json_extract(CASE WHEN slot.type='object' THEN slot.value ELSE '{}' END,'$.cid')=player_rankings.char_id AND json_extract(CASE WHEN slot.type='object' THEN slot.value ELSE '{}' END,'$.mode')=player_rankings.mode LIMIT 1),0) WHERE actor_key LIKE 'account:%' AND reborn=0;
CREATE INDEX IF NOT EXISTS player_rankings_power ON player_rankings(mode,power DESC,lvl DESC,xp DESC,name ASC);
